inputs = ['cau', 'du', 'ibbfi', 'yuf', 'ey']
outputs = ['cjw', 'djw', 'gjkbbagjk', 'yjwa', 'ey']

# Let's manually analyze each case
examples = list(zip(inputs, outputs))
for i, (inp, outp) in enumerate(examples):
    print(f"Example {i}: '{inp}' -> '{outp}'")
    if inp != outp:
        # Find where they differ
        min_len = min(len(inp), len(outp))
        diff_pos = None
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_pos = j
                break

        if diff_pos is not None:
            print(f"  First difference at position {diff_pos}")
            print(f"  Input char: '{inp[diff_pos]}'")
            print(f"  Output char: '{outp[diff_pos]}'")
        else:
            if len(inp) != len(outp):
                print(f"  Length difference: {len(inp)} -> {len(outp)}")
    print()

